from __future__ import annotations

import base64
import gzip
from pathlib import Path

UNIT_B64 = ""
TEST_B64 = ""


def decode_payload(payload: str) -> str:
    return gzip.decompress(base64.b64decode(payload)).decode("utf-8")


unit = decode_payload(UNIT_B64)
test = decode_payload(TEST_B64)

source = Path("data/course_redevelopment/etica-responsabilidad-social/units/unit-03.json")
mirror = Path("data/generated_units/etica-responsabilidad-social/unit-03.json")
regression = Path("tests/test_etica_responsabilidad_social_unit_03_curated.py")

source.write_text(unit, encoding="utf-8")
mirror.write_text(unit, encoding="utf-8")
regression.write_text(test, encoding="utf-8")

assert source.read_bytes() == mirror.read_bytes()
assert "concepto de la unidad que debe definirse mediante entidades observables" not in unit.casefold()
assert "V(a)=" not in unit
print("[ok] Ética y Responsabilidad Social U3 curada y espejada")
